from typing import List

class Solution:
    def permuteUnique(self, nums: List[int]) -> List[List[int]]:
        found = set()
        path = []
        used = [False] * len(nums)

        def dfs() -> None:
            if len(path) == len(nums):
                found.add(tuple(path))
                return
            for i, value in enumerate(nums):
                if used[i]:
                    continue
                used[i] = True
                path.append(value)
                dfs()
                path.pop()
                used[i] = False

        dfs()
        return [list(p) for p in sorted(found)]

